window.SBL_IGCSE_PPQ = {"topic": "Cambridge IGCSE Economics 0455", "img": "/igcse/cie-economics/past-papers/img/", "lessons": {"CIEE01": {"n": 1, "title": "Scarcity, factors of production and opportunity cost", "href": "/igcse/cie-economics/basic-economic-problem/topic-1-scarcity-factors-and-opportunity-cost"}, "CIEE02": {"n": 2, "title": "Production possibility curves", "href": "/igcse/cie-economics/basic-economic-problem/topic-2-production-possibility-curves"}, "CIEE03": {"n": 3, "title": "Markets, demand and supply", "href": "/igcse/cie-economics/allocation-of-resources/topic-3-markets-demand-and-supply"}, "CIEE04": {"n": 4, "title": "Price determination and price changes", "href": "/igcse/cie-economics/allocation-of-resources/topic-4-price-determination-and-price-changes"}, "CIEE05": {"n": 5, "title": "Price elasticity of demand and supply", "href": "/igcse/cie-economics/allocation-of-resources/topic-5-price-elasticity"}, "CIEE06": {"n": 6, "title": "The market economy and market failure", "href": "/igcse/cie-economics/allocation-of-resources/topic-6-market-economy-and-market-failure"}, "CIEE07": {"n": 7, "title": "The mixed economy and government intervention", "href": "/igcse/cie-economics/allocation-of-resources/topic-7-mixed-economy-and-government-intervention"}, "CIEE08": {"n": 8, "title": "Money, banking and households", "href": "/igcse/cie-economics/microeconomic-decision-makers/topic-8-money-banking-and-households"}, "CIEE09": {"n": 9, "title": "Workers: occupations, wages and the division of labour", "href": "/igcse/cie-economics/microeconomic-decision-makers/topic-9-workers"}, "CIEE10": {"n": 10, "title": "Firms, mergers and economies of scale", "href": "/igcse/cie-economics/microeconomic-decision-makers/topic-10-firms-mergers-and-economies-of-scale"}, "CIEE11": {"n": 11, "title": "Production, productivity, costs and revenue", "href": "/igcse/cie-economics/microeconomic-decision-makers/topic-11-production-costs-and-revenue"}, "CIEE12": {"n": 12, "title": "Objectives of firms and types of market", "href": "/igcse/cie-economics/microeconomic-decision-makers/topic-12-objectives-of-firms-and-types-of-market"}, "CIEE13": {"n": 13, "title": "Macroeconomic aims and fiscal policy", "href": "/igcse/cie-economics/government-and-the-macroeconomy/topic-13-macroeconomic-aims-and-fiscal-policy"}, "CIEE14": {"n": 14, "title": "Monetary policy and supply-side policy", "href": "/igcse/cie-economics/government-and-the-macroeconomy/topic-14-monetary-and-supply-side-policy"}, "CIEE15": {"n": 15, "title": "Economic growth and recession", "href": "/igcse/cie-economics/government-and-the-macroeconomy/topic-15-economic-growth-and-recession"}, "CIEE16": {"n": 16, "title": "Employment and unemployment", "href": "/igcse/cie-economics/government-and-the-macroeconomy/topic-16-employment-and-unemployment"}, "CIEE17": {"n": 17, "title": "Inflation and deflation", "href": "/igcse/cie-economics/government-and-the-macroeconomy/topic-17-inflation-and-deflation"}, "CIEE18": {"n": 18, "title": "Living standards and poverty", "href": "/igcse/cie-economics/economic-development/topic-18-living-standards-and-poverty"}, "CIEE19": {"n": 19, "title": "Population and differences in economic development", "href": "/igcse/cie-economics/economic-development/topic-19-population-and-differences-in-development"}, "CIEE20": {"n": 20, "title": "Specialisation, free trade, globalisation and MNCs", "href": "/igcse/cie-economics/international-trade-and-globalisation/topic-20-specialisation-free-trade-and-globalisation"}, "CIEE21": {"n": 21, "title": "Trade restrictions (protection)", "href": "/igcse/cie-economics/international-trade-and-globalisation/topic-21-trade-restrictions"}, "CIEE22": {"n": 22, "title": "Foreign exchange rates", "href": "/igcse/cie-economics/international-trade-and-globalisation/topic-22-foreign-exchange-rates"}, "CIEE23": {"n": 23, "title": "The current account of the balance of payments", "href": "/igcse/cie-economics/international-trade-and-globalisation/topic-23-current-account-of-the-balance-of-payments"}}, "parts": [{"key": "sp1-1", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 1, "id": "1", "marks": 1, "text": "A firm produces two types of battery. It supplies car batteries to firms that make electric cars and laptop batteries to firms that make computers. What is an example of the basic economic question ‘what to produce’?", "intro": "", "options": [["A", "How many car batteries and how many laptop batteries should be manufactured?"], ["B", "How many workers and how many machines should be used to produce each type of battery?"], ["C", "What proportion of batteries should be produced for export and what proportion for domestic consumers?"], ["D", "What proportion of recycled materials should be used in the manufacture of the batteries?"]], "answer": "A", "type": "mcq", "lesson": "CIEE01", "ms": "Answer: A\nDeciding the quantities of each product to make is the ‘what to produce’ question. B and D are ‘how to produce’; C is ‘for whom’.", "sources": []}, {"key": "sp1-2", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 2, "id": "2", "marks": 1, "text": "What is a free good?", "intro": "", "options": [["A", "a good for which demand is less than supply"], ["B", "a good produced using few resources"], ["C", "a good that has no opportunity cost"], ["D", "a good that is provided by the state"]], "answer": "C", "type": "mcq", "lesson": "CIEE01", "ms": "Answer: C\nA free good is unlimited in supply, so it has no opportunity cost. Goods provided by the state still use scarce resources.", "sources": []}, {"key": "sp1-3", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 3, "id": "3", "marks": 1, "text": "Which factor of production is rewarded with rent?", "intro": "", "options": [["A", "capital"], ["B", "enterprise"], ["C", "labour"], ["D", "land"]], "answer": "D", "type": "mcq", "lesson": "CIEE01", "ms": "Answer: D\nLand earns rent; labour earns wages; capital earns interest; enterprise earns profit.", "sources": []}, {"key": "sp1-4", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 4, "id": "4", "marks": 1, "text": "The diagram shows the demand for smartphones (initial demand curve D1, initial equilibrium E1). Data for internet access has to be purchased separately. What is the effect of an increase in the price of data for internet access on the demand for smartphones?", "intro": "", "options": [["A", "a shift of the demand curve to D2"], ["B", "a shift of the demand curve to D3"], ["C", "movement along the demand curve to E2"], ["D", "movement along the demand curve to E3"]], "answer": "B", "type": "mcq", "lesson": "CIEE03", "ms": "Answer: B\nData and smartphones are complements. A rise in the price of a complement reduces demand for smartphones: the demand curve shifts left to D3.", "sources": [{"src": "sp1-q04.png", "figs": []}]}, {"key": "sp1-5", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 5, "id": "5", "marks": 1, "text": "The initial supply curve of a firm’s good is S1, as shown on the diagram. What will cause the supply curve to shift to S2?", "intro": "", "options": [["A", "an increase in the number of sick days taken by the firm’s workers"], ["B", "an increase in the cost of training the firm’s workers"], ["C", "an increase in the productivity of the firm’s workers"], ["D", "an increase in the wage rate paid to the firm’s workers"]], "answer": "C", "type": "mcq", "lesson": "CIEE03", "ms": "Answer: C\nS2 is to the right of S1 (an increase in supply). Higher productivity lowers costs per unit; the other options raise costs and would shift supply left.", "sources": [{"src": "sp1-q05.png", "figs": []}]}, {"key": "sp1-6", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 6, "id": "6", "marks": 1, "text": "A firm reduces the price of its product from $100 to $90. The quantity demanded increases from 1000 to 1500. What is the price elasticity of demand (PED)?", "intro": "", "options": [["A", "–0.1"], ["B", "–0.2"], ["C", "–0.5"], ["D", "–5.0"]], "answer": "D", "type": "mcq", "lesson": "CIEE05", "ms": "Answer: D\n% change in quantity demanded = +50%; % change in price = −10%. PED = 50 ÷ −10 = −5.0.", "sources": []}, {"key": "sp1-7", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 7, "id": "7", "marks": 1, "text": "What can a government analyse through the use of price elasticity of demand (PED)?", "intro": "", "options": [["A", "how a change in income tax affects a current account deficit"], ["B", "how a tax on the production of a good affects tax revenue"], ["C", "how changes in the rate of interest affect unemployment"], ["D", "how providing more merit goods affects social welfare"]], "answer": "B", "type": "mcq", "lesson": "CIEE05", "ms": "Answer: B\nPED shows how much quantity demanded falls when a tax raises the price, and so how much tax revenue the government will collect.", "sources": []}, {"key": "sp1-8", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 8, "id": "8", "marks": 1, "text": "A firm cannot obtain the additional raw materials needed to increase production of a good above 50 000 units. What is the price elasticity of supply (PES) at 50 000 units if the price of the good increases by 10%?", "intro": "", "options": [["A", "0"], ["B", "0.1"], ["C", "1"], ["D", "10"]], "answer": "A", "type": "mcq", "lesson": "CIEE05", "ms": "Answer: A\nQuantity supplied cannot change, so the % change in quantity supplied is 0 and PES = 0 (perfectly inelastic).", "sources": []}, {"key": "sp1-9", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 9, "id": "9", "marks": 1, "text": "A monopolist uses oil in its production process that causes pollution. The monopolist is efficient at producing large quantities of its product which is sold at a very low price. What is the likely cause of market failure?", "intro": "", "options": [["A", "abuse of monopoly power"], ["B", "demerit goods"], ["C", "diseconomies of scale"], ["D", "external costs of production"]], "answer": "D", "type": "mcq", "lesson": "CIEE06", "ms": "Answer: D\nThe monopolist is efficient and charges low prices, so it is not abusing its power. The pollution is an external cost of production.", "sources": []}, {"key": "sp1-10", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 10, "id": "10", "marks": 1, "text": "The diagram shows the market for a good. The equilibrium is at point X. The government fixes a maximum price for the good at P2. What will happen in the market as a result?", "intro": "", "options": [["A", "The market equilibrium will remain the same."], ["B", "The quantity demanded will fall to Q3."], ["C", "There will be excess demand."], ["D", "There will be excess supply."]], "answer": "C", "type": "mcq", "lesson": "CIEE07", "ms": "Answer: C\nP2 is below the equilibrium price, so quantity demanded (Q2) exceeds quantity supplied (Q3): excess demand (a shortage).", "sources": [{"src": "sp1-q10.png", "figs": []}]}, {"key": "sp1-11", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 11, "id": "11", "marks": 1, "text": "Which function does a central bank provide that a commercial bank does not provide?", "intro": "", "options": [["A", "acting as the government’s bank"], ["B", "dealing with foreign exchange"], ["C", "providing loans to the public"], ["D", "providing savings accounts for the public"]], "answer": "A", "type": "mcq", "lesson": "CIEE08", "ms": "Answer: A\nOnly the central bank is the government’s bank. Commercial banks deal in foreign exchange, lend and offer savings accounts.", "sources": []}, {"key": "sp1-12", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 12, "id": "12", "marks": 1, "text": "Which group of people is most likely to save the largest proportion of their income?", "intro": "", "options": [["A", "middle-aged people"], ["B", "people earning the minimum wage"], ["C", "people with young children"], ["D", "young people"]], "answer": "A", "type": "mcq", "lesson": "CIEE08", "ms": "Answer: A\nMiddle-aged people usually earn the most and save for retirement; the other groups spend most of their income.", "sources": []}, {"key": "sp1-13", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 13, "id": "13", "marks": 1, "text": "When would a trade union be least likely to achieve an increase in the wage rate of its members?", "intro": "", "options": [["A", "when a competitor firm successfully introduces a substitute product"], ["B", "when labour costs form a low percentage of the firm’s total costs"], ["C", "when the firm introduces labour-intensive production methods"], ["D", "when the firm is making large profits"]], "answer": "A", "type": "mcq", "lesson": "CIEE09", "ms": "Answer: A\nIf a rival introduces a substitute, demand for the firm’s product (and so for its labour) falls, weakening the union’s bargaining power.", "sources": []}, {"key": "sp1-14", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 14, "id": "14", "marks": 1, "text": "The diagram shows the initial demand for labour D1 and supply of labour S1 for a firm, with the initial equilibrium at X. The government then builds new transport links that connect a wider population to the firm’s place of work. What is the new equilibrium point?", "intro": "", "options": [["A", "A"], ["B", "B"], ["C", "C"], ["D", "D"]], "answer": "C", "type": "mcq", "lesson": "CIEE09", "ms": "Answer: C\nBetter transport increases the supply of labour (S1 to S3) while demand stays at D1. The new equilibrium is where D1 meets S3: point C (lower wage, more hours worked).", "sources": [{"src": "sp1-q14.png", "figs": []}]}, {"key": "sp1-15", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 15, "id": "15", "marks": 1, "text": "Which disadvantage is likely to result from increased division of labour within manufacturing?", "intro": "", "options": [["A", "For a consumer, there are more handmade goods."], ["B", "For a consumer, there is an increase in the quality of goods."], ["C", "For an employee, job security will increase."], ["D", "For an employee, the nature of their work is less varied."]], "answer": "D", "type": "mcq", "lesson": "CIEE09", "ms": "Answer: D\nDivision of labour means repeating the same task, so work becomes less varied and can be boring.", "sources": []}, {"key": "sp1-16", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 16, "id": "16", "marks": 1, "text": "The owners of a chain of pizza restaurants decide to buy a chain of burger restaurants to increase revenue. Which term describes this action?", "intro": "", "options": [["A", "horizontal merger"], ["B", "nationalisation"], ["C", "privatisation"], ["D", "vertical merger"]], "answer": "A", "type": "mcq", "lesson": "CIEE10", "ms": "Answer: A\nBoth firms are restaurants at the same stage of production, so it is a horizontal merger.", "sources": []}, {"key": "sp1-17", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 17, "id": "17", "marks": 1, "text": "Why might a government encourage a competitive market?", "intro": "", "options": [["A", "Competitive markets create high prices."], ["B", "Competitive markets generate large advertising costs."], ["C", "Competitive markets prevent innovation."], ["D", "Competitive markets provide greater consumer choice."]], "answer": "D", "type": "mcq", "lesson": "CIEE12", "ms": "Answer: D\nCompetition gives consumers more choice (and usually lower prices and better quality).", "sources": []}, {"key": "sp1-18", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 18, "id": "18", "marks": 1, "text": "A firm buys new machinery to produce a greater output per machine. The firm trains some of its workers to operate these machines but makes a larger number of workers unemployed. What is the effect on the productivity of capital and on the productivity of labour?", "intro": "", "options": [["A", "capital falls, labour falls"], ["B", "capital rises, labour rises"], ["C", "capital falls, labour rises"], ["D", "capital rises, labour falls"]], "answer": "B", "type": "mcq", "lesson": "CIEE11", "ms": "Answer: B\nOutput per machine rises, and output is produced with fewer, better-trained workers, so output per worker also rises.", "sources": [{"src": "sp1-q18.png", "figs": []}]}, {"key": "sp1-19", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 19, "id": "19", "marks": 1, "text": "The diagrams show the average total cost (ATC) curves of four firms and how they change as output increases. Which firm has the lowest fixed costs?", "intro": "", "options": [["A", "A"], ["B", "B"], ["C", "C"], ["D", "D"]], "answer": "D", "type": "mcq", "lesson": "CIEE11", "ms": "Answer: D\nFixed costs make ATC high at low output and then fall as they are spread. Firm D’s ATC starts at zero and rises, so it has the lowest (no) fixed costs.", "sources": [{"src": "sp1-q19.png", "figs": []}]}, {"key": "sp1-20", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 20, "id": "20", "marks": 1, "text": "What is true in a monopoly market?", "intro": "", "options": [["A", "Consumers enjoy a large variety of product choice."], ["B", "Firms with limited finance find it difficult to enter the market."], ["C", "High levels of profit are unusual."], ["D", "The costs of production are always higher than in a competitive market."]], "answer": "B", "type": "mcq", "lesson": "CIEE12", "ms": "Answer: B\nMonopolies are protected by high barriers to entry, such as high start-up costs.", "sources": []}, {"key": "sp1-21", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 21, "id": "21", "marks": 1, "text": "What is least likely to be directly affected by the government?", "intro": "", "options": [["A", "the interest a firm receives from its money in the bank"], ["B", "the minimum wage a firm must pay to its workers"], ["C", "the selection of a new manager at a firm"], ["D", "the working conditions of employees at a firm"]], "answer": "C", "type": "mcq", "lesson": "CIEE07", "ms": "Answer: C\nGovernments set interest rates (via the central bank), minimum wages and working-condition regulations, but not a private firm’s choice of manager.", "sources": []}, {"key": "sp1-22", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 22, "id": "22", "marks": 1, "text": "Protection of the environment is a key macroeconomic aim. Which policy measure is most likely to achieve this?", "intro": "", "options": [["A", "deregulation that allows factories to be built in rural areas"], ["B", "investment in transport infrastructure that increases tourism"], ["C", "regulation that bans the driving of cars in city centres"], ["D", "subsidising coal power stations to meet the energy needs of electric vehicles"]], "answer": "C", "type": "mcq", "lesson": "CIEE13", "ms": "Answer: C\nBanning cars in city centres directly reduces pollution; the other options increase environmental damage.", "sources": []}, {"key": "sp1-23", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 23, "id": "23", "marks": 1, "text": "The table shows a government’s revenue from taxation: tax on company profits $100m; income tax $600m; import duties $30m; sales tax $250m. What is the total amount raised by indirect taxes?", "intro": "", "options": [["A", "$250m"], ["B", "$280m"], ["C", "$700m"], ["D", "$980m"]], "answer": "B", "type": "mcq", "lesson": "CIEE13", "ms": "Answer: B\nIndirect taxes are import duties ($30m) + sales tax ($250m) = $280m. Taxes on profits and income are direct.", "sources": [{"src": "sp1-q23.png", "figs": []}]}, {"key": "sp1-24", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 24, "id": "24", "marks": 1, "text": "The table shows selected statistics for an economy ($bn): exports 600; imports 700; government expenditure 550; government revenue 400. What is the government’s budget position in terms of deficit or surplus?", "intro": "", "options": [["A", "a deficit of $100 billion"], ["B", "a deficit of $150 billion"], ["C", "a surplus of $100 billion"], ["D", "a surplus of $300 billion"]], "answer": "B", "type": "mcq", "lesson": "CIEE13", "ms": "Answer: B\nThe budget compares government spending and revenue: 550 − 400 = a deficit of $150bn. Exports and imports are not part of the budget.", "sources": [{"src": "sp1-q24.png", "figs": []}]}, {"key": "sp1-25", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 25, "id": "25", "marks": 1, "text": "What is the most likely result of a fall in interest rates?", "intro": "", "options": [["A", "a decrease in household saving"], ["B", "a decrease in new bank loans"], ["C", "an increase in labour-intensive production"], ["D", "an increase in relative poverty"]], "answer": "A", "type": "mcq", "lesson": "CIEE14", "ms": "Answer: A\nLower interest rates reduce the reward for saving, so households save less (and borrow more).", "sources": []}, {"key": "sp1-26", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 26, "id": "26", "marks": 1, "text": "What is a supply-side policy measure that aims to increase economic growth?", "intro": "", "options": [["A", "raising indirect taxation"], ["B", "reducing the state retirement age"], ["C", "removing the limit on maximum working hours"], ["D", "restricting land available for industrial building"]], "answer": "C", "type": "mcq", "lesson": "CIEE14", "ms": "Answer: C\nRemoving the limit on working hours increases the quantity of labour available, raising productive capacity.", "sources": []}, {"key": "sp1-27", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 27, "id": "27", "marks": 1, "text": "A government subsidised the building of new homes in a rural area to increase labour mobility. It also built a new school. Some people claimed these developments would take land previously used for farming. Which concepts are involved in this statement?", "intro": "", "options": [["A", "government intervention, monetary policy, public goods"], ["B", "market disequilibrium, economic growth, resource allocation"], ["C", "market prices, external benefits, monetary policy"], ["D", "supply-side policy, factors of production, opportunity cost"]], "answer": "D", "type": "mcq", "lesson": "CIEE14", "ms": "Answer: D\nImproving labour mobility and building a school are supply-side measures; land is a factor of production; losing farmland is the opportunity cost.", "sources": []}, {"key": "sp1-28", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 28, "id": "28", "marks": 1, "text": "What will limit the harmful impact of economic growth on the environment?", "intro": "", "options": [["A", "increased clearing of forests to grow more crops for food"], ["B", "increased pollution as industry expands"], ["C", "increased use of an economy’s oil and natural gas resources"], ["D", "increased use of renewable energy resources"]], "answer": "D", "type": "mcq", "lesson": "CIEE15", "ms": "Answer: D\nRenewable energy reduces pollution and resource depletion.", "sources": []}, {"key": "sp1-29", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 29, "id": "29", "marks": 1, "text": "What is not likely to cause a recession?", "intro": "", "options": [["A", "a government reducing its spending"], ["B", "a natural disaster caused by climate change"], ["C", "mining a new source of a useful metal"], ["D", "problems with global supply of raw materials"]], "answer": "C", "type": "mcq", "lesson": "CIEE15", "ms": "Answer: C\nA new source of a useful metal increases the quantity of resources, which supports growth rather than recession.", "sources": []}, {"key": "sp1-30", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 30, "id": "30", "marks": 1, "text": "The table shows unemployment and inflation for the US, Japan and Sweden in years 1 and 2 (unemployment %: US 4.8 → 4.4, Japan 2.7 → 2.7, Sweden 2.7 → 3.2; inflation %: US 5.6 → 3.4, Japan 1.7 → 0.7, Sweden 8.3 → 6.6). Which conclusion can be made from the table?", "intro": "", "options": [["A", "In year 1, the same number of people were unemployed in Sweden and Japan."], ["B", "In year 2, the cost of living increased in the US."], ["C", "The number of unemployed people increased in all three countries."], ["D", "Unemployment and inflation moved in the same direction in Sweden."]], "answer": "B", "type": "mcq", "lesson": "CIEE16", "ms": "Answer: B\nUS inflation was positive (3.4%) in year 2, so prices (the cost of living) still rose. Rates are percentages, so A cannot be concluded.", "sources": [{"src": "sp1-q30.png", "figs": []}]}, {"key": "sp1-31", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 31, "id": "31", "marks": 1, "text": "What is an example of frictional unemployment?", "intro": "", "options": [["A", "young people spending time to search for a job after finishing school"], ["B", "young people taking a three-month holiday between finishing school and starting a job"], ["C", "young people who cannot find a job because there is a recession in the economy"], ["D", "young people who have the wrong skills to work in industries that use new technology"]], "answer": "A", "type": "mcq", "lesson": "CIEE16", "ms": "Answer: A\nFrictional unemployment is the time spent between jobs or searching for a job. B is voluntary, C is cyclical and D is structural.", "sources": []}, {"key": "sp1-32", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 32, "id": "32", "marks": 1, "text": "Which combination of government policy measures is most likely to reduce unemployment?", "intro": "", "options": [["A", "an increase in expenditure on healthcare and subsidies for capital-intensive production"], ["B", "an increase in expenditure on training and an increase in corporation tax"], ["C", "an increase in import tariffs and a decrease in interest rates"], ["D", "an increase in income tax and an increase in quotas on imported goods"]], "answer": "C", "type": "mcq", "lesson": "CIEE16", "ms": "Answer: C\nTariffs protect domestic jobs and lower interest rates increase total demand; in each other option one measure works against employment.", "sources": []}, {"key": "sp1-33", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 33, "id": "33", "marks": 1, "text": "In the construction of a Consumer Prices Index (CPI), a total weighting of 1000 is used. A weight of 200 is given to transport and a weight of 100 is given to clothing. What must be true?", "intro": "", "options": [["A", "Clothing prices are rising half as fast as transport prices."], ["B", "Consumers spend more on basic needs than on luxury goods."], ["C", "Consumers spend twice as much on transport as they do on clothing."], ["D", "Transport has the greatest weight of all items in the CPI."]], "answer": "C", "type": "mcq", "lesson": "CIEE17", "ms": "Answer: C\nWeights reflect the share of household spending, so spending on transport is twice that on clothing.", "sources": []}, {"key": "sp1-34", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 34, "id": "34", "marks": 1, "text": "When comparing living standards, what makes the Human Development Index (HDI) a more useful indicator than real Gross Domestic Product (GDP) per head?", "intro": "", "options": [["A", "HDI includes a range of measures."], ["B", "HDI includes the import and export of goods and services."], ["C", "HDI is directly linked to poverty reduction."], ["D", "HDI is measured in local currency."]], "answer": "A", "type": "mcq", "lesson": "CIEE18", "ms": "Answer: A\nThe HDI combines health, education and income, so it measures more than income alone.", "sources": []}, {"key": "sp1-35", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 35, "id": "35", "marks": 1, "text": "The table gives GDP, population and GDP per head for: Bangladesh ($2 688), Chile ($15 351), South Africa ($6 776), Trinidad and Tobago ($18 289). Based on the data, which country has the highest standard of living?", "intro": "", "options": [["A", "Bangladesh"], ["B", "Chile"], ["C", "South Africa"], ["D", "Trinidad and Tobago"]], "answer": "D", "type": "mcq", "lesson": "CIEE18", "ms": "Answer: D\nTrinidad and Tobago has the highest GDP per head ($18 289).", "sources": [{"src": "sp1-q35.png", "figs": []}]}, {"key": "sp1-36", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 36, "id": "36", "marks": 1, "text": "What is meant by the optimum population for a country?", "intro": "", "options": [["A", "a population that consumes the fewest demerit goods"], ["B", "a population that generates the maximum tax revenue"], ["C", "a population that has the greatest life expectancy"], ["D", "a population that produces the maximum output per head"]], "answer": "D", "type": "mcq", "lesson": "CIEE19", "ms": "Answer: D\nThe optimum population is the size at which output (GDP) per head is maximised.", "sources": []}, {"key": "sp1-37", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 37, "id": "37", "marks": 1, "text": "What is least likely to be found in a high-income country?", "intro": "", "options": [["A", "a low GDP per head and a high level of car ownership"], ["B", "a low level of labour skills and a high level of employment"], ["C", "a low rate of adult literacy and a high level of absolute poverty"], ["D", "a low rate of population growth and a high life expectancy"]], "answer": "C", "type": "mcq", "lesson": "CIEE19", "ms": "Answer: C\nHigh-income countries usually have high literacy and little absolute poverty.", "sources": []}, {"key": "sp1-38", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 38, "id": "38", "marks": 1, "text": "What is not a reason for imposing international trade restrictions?", "intro": "", "options": [["A", "to protect consumers from high prices charged by domestic monopoly suppliers"], ["B", "to protect domestic producers from imported goods priced below the cost of production"], ["C", "to protect households from imported drugs and harmful products"], ["D", "to protect the environment from damage and encourage sustainability"]], "answer": "A", "type": "mcq", "lesson": "CIEE21", "ms": "Answer: A\nTrade restrictions reduce competition from imports, which would make it easier for domestic monopolies to charge high prices.", "sources": []}, {"key": "sp1-39", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 39, "id": "39", "marks": 1, "text": "The price of a good produced in the United States (US) is $10 and this good is exported to South Africa. The initial exchange rate is $1 = 20 ZAR. It then changes to $1 = 19 ZAR. How does the price of the good change in South Africa?", "intro": "", "options": [["A", "price decreases by 1 ZAR"], ["B", "price decreases by 10 ZAR"], ["C", "price increases by 1 ZAR"], ["D", "price increases by 10 ZAR"]], "answer": "B", "type": "mcq", "lesson": "CIEE22", "ms": "Answer: B\nBefore: 10 × 20 = 200 ZAR. After: 10 × 19 = 190 ZAR. The price falls by 10 ZAR.", "sources": []}, {"key": "sp1-40", "paper": "sp-p1", "paperLabel": "Specimen Paper 1 (Multiple choice)", "q": 40, "id": "40", "marks": 1, "text": "The diagrams show the levels of exports and imports of a country: exports $120 million (goods 50%, services 50%); imports $100 million (goods 60%, services 40%). What is true for this country?", "intro": "", "options": [["A", "Exports of goods are worth $60 million."], ["B", "Imports of goods are worth $50 million."], ["C", "Exports of services are worth $50 million."], ["D", "Imports of services are worth $60 million."]], "answer": "A", "type": "mcq", "lesson": "CIEE23", "ms": "Answer: A\n50% of $120m = $60m exports of goods. Imports of goods = $60m and imports of services = $40m.", "sources": [{"src": "sp1-q40.png", "figs": []}]}, {"key": "sp2-1a", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 1, "id": "1(a)", "marks": 2, "text": "Calculate the value of Algeria’s primary sector output in 2023. Show your working.", "intro": "Changes in the Algerian economy. Read the information in the Resource Booklet (Table 1.1 Algeria fact file 2023 and Table 1.2 Life expectancy and net migration rate in selected countries). In your answers to Question 1, you must use the information provided.", "type": "written", "lesson": "CIEE15", "ms": "Correct answer: $31.2bn (2).\nCorrect method but incorrect answer: GDP × primary sector’s share of GDP (1); $208bn × 15/100 (1).", "sources": [{"src": "sp2-q1.png", "figs": []}]}, {"key": "sp2-1b", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 1, "id": "1(b)", "marks": 2, "text": "Identify two capital goods employed in Algeria’s primary sector.", "intro": "Changes in the Algerian economy. Read the information in the Resource Booklet (Table 1.1 Algeria fact file 2023 and Table 1.2 Life expectancy and net migration rate in selected countries). In your answers to Question 1, you must use the information provided.", "type": "written", "lesson": "CIEE01", "ms": "1 mark for each capital good, up to 2: drilling machinery (1); irrigation / watering equipment (1); buildings (1). Must be selected from the source information.", "sources": [{"src": "sp2-q1.png", "figs": []}]}, {"key": "sp2-1c", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 1, "id": "1(c)", "marks": 2, "text": "Explain one reason why productivity increased in Algeria’s tertiary sector.", "intro": "Changes in the Algerian economy. Read the information in the Resource Booklet (Table 1.1 Algeria fact file 2023 and Table 1.2 Life expectancy and net migration rate in selected countries). In your answers to Question 1, you must use the information provided.", "type": "written", "lesson": "CIEE11", "ms": "1 mark for identification, 1 mark for explanation:\n• Improvements in education (1) are likely to increase workers’ skills (1).\n• Advances in technology (1) will enable workers to work with better capital equipment (1).\n• Rise in wages (1) may increase the motivation of workers (1).", "sources": [{"src": "sp2-q1.png", "figs": []}]}, {"key": "sp2-1d", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 1, "id": "1(d)", "marks": 4, "text": "Draw a demand and supply diagram to show the effect of an increase in vegetarianism on the market for tomatoes.", "intro": "Changes in the Algerian economy. Read the information in the Resource Booklet (Table 1.1 Algeria fact file 2023 and Table 1.2 Life expectancy and net migration rate in selected countries). In your answers to Question 1, you must use the information provided.", "type": "draw", "lesson": "CIEE04", "ms": "• Axes correctly labelled (price and quantity) (1).\n• Original demand and supply curves D1 and S1 correctly labelled (1).\n• New demand curve D2 shifted to the right (1).\n• Equilibriums shown by P1 and Q1 and P2 and Q2, or points E1 and E2 (1).\nNo marks for written analysis.", "sources": [{"src": "sp2-q1.png", "figs": []}]}, {"key": "sp2-1e", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 1, "id": "1(e)", "marks": 4, "text": "Analyse the relationship between life expectancy and the net migration rate.", "intro": "Changes in the Algerian economy. Read the information in the Resource Booklet (Table 1.1 Algeria fact file 2023 and Table 1.2 Life expectancy and net migration rate in selected countries). In your answers to Question 1, you must use the information provided.", "type": "written", "lesson": "CIEE19", "ms": "Up to 4 marks: 1 mark for the expected relationship; up to 2 for supporting evidence; up to 2 for analysis; 1 for an exception; 1 for evidence of the exception; 1 for analysis of the exception.\n• Expected relationship: high life expectancy accompanied by a positive net migration rate (net immigration) / a positive relationship (1).\n• Evidence: Monaco has the longest life expectancy and highest net immigration (1); the three countries with life expectancy over 80 had net immigration (1).\n• Analysis: long life expectancy suggests good healthcare / high living standards (1), which may encourage people to move to the country (1).\n• Exception: Fiji / Tonga (1): Fiji had a lower life expectancy than Tonga but less net emigration (1). Other influences on migration, e.g. immigration controls (1).", "sources": [{"src": "sp2-q1.png", "figs": []}]}, {"key": "sp2-1f", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 1, "id": "1(f)", "marks": 6, "text": "Discuss whether or not the Algerian Government should impose a carbon tax.", "intro": "Changes in the Algerian economy. Read the information in the Resource Booklet (Table 1.1 Algeria fact file 2023 and Table 1.2 Life expectancy and net migration rate in selected countries). In your answers to Question 1, you must use the information provided.", "type": "written", "lesson": "CIEE13", "ms": "Up to 4 marks for reasons why it should: pressure on firms to reduce CO2 emissions (1), reduce external costs (1), reduce misallocation of resources (1), increase life expectancy / living standards (1); reduce soil erosion (1), let farm workers work longer (1), increase agricultural output (1); reduce extreme weather damage to buildings/crops/tourism (1), raise GDP (1), incomes (1), tax revenue (1); helps the aim of environmental protection (1).\nUp to 4 marks for reasons why it should not: if other countries do not impose a carbon tax (1) Algeria’s products may be less competitive (1), exports may fall (1), firms may move abroad (1), global pollution may not fall (1); Algeria produces large quantities of oil and gas (1), so employment in these industries may fall (1); likely to be regressive (1), falling more heavily on the poor (1); expensive / complicated to operate (1).\nEach point credited once; reward separate development, not the reverse of a previous argument.", "sources": [{"src": "sp2-q1.png", "figs": []}]}, {"key": "sp2-2a", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 2, "id": "2(a)", "marks": 2, "text": "Define ‘international trade’.", "intro": "Sweden’s population enjoys high living standards. The country is heavily dependent on international trade. Every year between 2000 and 2023, Sweden had a surplus on the current account of its balance of payments. Over this period, Sweden’s unemployment rate averaged 7.7%. It was forecast that Sweden’s unemployment rate would fall and its current account surplus would increase between 2023 and 2030.", "type": "written", "lesson": "CIEE20", "ms": "The exchange of goods (and services) (1) between countries (1).", "sources": []}, {"key": "sp2-2b", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 2, "id": "2(b)", "marks": 4, "text": "Explain two consequences for firms of a decrease in their country’s unemployment rate.", "intro": "Sweden: high living standards; heavily dependent on international trade; current account surplus every year 2000–2023; unemployment averaged 7.7%; unemployment forecast to fall and the surplus to increase to 2030.", "type": "written", "lesson": "CIEE16", "ms": "1 mark for identification and 1 for explanation (× 2):\n• Lower unemployment is likely to increase demand (1), raising firms’ revenue / profits (1).\n• Lower unemployment may increase workers’ wages (1) due to greater bargaining power / raising firms’ costs (1).\n• It may become difficult to recruit workers (1), which may stop firms expanding (1).", "sources": []}, {"key": "sp2-2c", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 2, "id": "2(c)", "marks": 6, "text": "Analyse two policy measures a government could use to reduce unemployment.", "intro": "Sweden: high living standards; heavily dependent on international trade; current account surplus every year 2000–2023; unemployment averaged 7.7%.", "type": "written", "lesson": "CIEE16", "ms": "Up to 2 marks for identifying two relevant policies; remaining marks for analysis:\n• Increase government spending / expansionary fiscal policy (1), increasing total demand (1), reducing cyclical unemployment (1).\n• Reduce the rate of interest / expansionary monetary policy (1): lower cost of borrowing (1), lower reward for saving (1), more consumer expenditure (1), more total demand (1), less cyclical unemployment (1).\n• Increase the money supply (1) by printing money / reducing restrictions on bank lending (1), increasing total demand (1).\n• Improve education, training or health / supply-side policy (1): more skills (1), more occupational mobility (1), less structural unemployment (1).\n• Spend on infrastructure (1): more geographical mobility (1), less structural unemployment (1).\n• More information on vacancies (1): less frictional unemployment (1).\n• Reduce unemployment benefit (1): bigger gap between work and benefits (1), more incentive to work (1), less frictional unemployment (1).\nDo not reward the same point twice.", "sources": []}, {"key": "sp2-2d", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 2, "id": "2(d)", "marks": 8, "text": "Discuss whether or not an increase in a surplus on the current account of the balance of payments will increase living standards in a country.", "intro": "Sweden: high living standards; heavily dependent on international trade; current account surplus every year 2000–2023.", "type": "written", "lesson": "CIEE23", "ms": "Levels of response (8 marks): Level 3 (6–8) a reasoned discussion that accurately considers both sides with clear, logical analysis; Level 2 (3–5) a reasoned discussion with some clear analysis but may lack depth or be one-sided; Level 1 (1–2) relevant definitions / undeveloped statements.\nWhy it will: increase demand and raise employment; higher employment may increase wages; higher wages let households consume more; more tax revenue for education and healthcare; may raise the exchange rate, making imports more affordable.\nWhy it will not: more goods and services leave the country; opportunity cost of exports; resources may be depleted, reducing future living standards; higher demand may cause demand-pull inflation; some incomes may not rise in line with prices; a higher exchange rate may reduce competitiveness, lowering exports and incomes.", "sources": []}, {"key": "sp2-3a", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 3, "id": "3(a)", "marks": 2, "text": "Identify the difference between external cost and social cost.", "intro": "In Grenada, the consumption of sugar per head is 92 grams a day. The World Health Organization recommends no more than 25 grams and encourages the daily use of toothpaste. The consumption of some food products can result in high external costs and high social costs. Governments can influence the products people buy in several ways. Nearby Venezuela sets a maximum price on rice and subsidises other products.", "type": "written", "lesson": "CIEE06", "ms": "External cost is a cost to a third party (1) whereas social cost is total cost / includes external and private costs (1). Or: private cost (2).", "sources": []}, {"key": "sp2-3b", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 3, "id": "3(b)", "marks": 4, "text": "Explain two causes of an increase in the price elasticity of demand for rice.", "intro": "Grenada: high sugar consumption; some food products have high external and social costs. Venezuela sets a maximum price on rice and subsidises other products.", "type": "written", "lesson": "CIEE05", "ms": "1 mark for identification and 1 for explanation (× 2):\n• Closer substitutes (1): fall in price / rise in quality of rival products (1).\n• An increase in income (1): rice takes up a smaller proportion of income (1).\n• Time period (1): the longer the time period, the more time people have to find alternatives (1).\n• Rice seen less as a necessity (1): other foods added to people’s diet (1).", "sources": []}, {"key": "sp2-3c", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 3, "id": "3(c)", "marks": 6, "text": "Analyse how the setting of a maximum price and a minimum price can result in market disequilibrium.", "intro": "Venezuela sets a maximum price on rice and subsidises other products.", "type": "written", "lesson": "CIEE07", "ms": "1 mark for stating (or showing on a diagram) where a maximum price is set and 1 for where a minimum price is set; remaining marks for analysis:\n• Maximum price below the equilibrium price (1): price falls (1), demand extends (1), supply contracts (1), a shortage / excess demand (1).\n• Minimum price above the equilibrium price (1): price rises (1), demand contracts (1), supply extends (1), a surplus / excess supply (1).", "sources": []}, {"key": "sp2-3d", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 3, "id": "3(d)", "marks": 8, "text": "Discuss whether or not a government should subsidise toothpaste.", "intro": "The World Health Organization recommends no more than 25 grams of sugar a day and encourages the daily use of toothpaste.", "type": "written", "lesson": "CIEE07", "ms": "Levels of response (8 marks) as for 2(d).\nWhy it should: toothpaste may be a merit good; consumers may under-estimate its true value; it may be under-consumed and under-produced; a subsidy could increase supply, lower price and cause demand to extend; more use could reduce tooth decay; lower healthcare costs.\nWhy it should not: toothpaste may be cheap and affordable anyway; rich consumers can afford it; a subsidy may make producers inefficient; it may not be passed on to consumers; it may go from under-consumed to over-consumed.", "sources": []}, {"key": "sp2-4a", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 4, "id": "4(a)", "marks": 2, "text": "Define ‘division of labour’.", "intro": "In Norway, more than 60% of new cars sold are electric cars. The production of electric cars makes extensive use of the division of labour. Some people save to buy a car. However, saving in Norway fell from 13% of disposable income in 2021 to 5% in 2023. The country also experienced changes in the types of jobs in which people were employed. For example, there was a decline in the number of people deciding to become teachers.", "type": "written", "lesson": "CIEE09", "ms": "The breaking down of production into separate tasks (1) and each worker concentrating on particular tasks (1).", "sources": []}, {"key": "sp2-4b", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 4, "id": "4(b)", "marks": 4, "text": "Explain two reasons why saving may decrease.", "intro": "Norway: saving fell from 13% of disposable income in 2021 to 5% in 2023.", "type": "written", "lesson": "CIEE08", "ms": "1 mark for identification and 1 for explanation (× 2):\n• Income may fall (1): people have to spend a higher proportion of income (1).\n• A reduction in the interest rate (1) reduces the reward for saving (1).\n• Greater confidence in the future (1): less need for a safety net (1).\n• Fewer saving schemes available (1) to suit people’s needs (1).\n• Less trust in financial institutions (1) (1).\n• Change in the age of the population (1): older people using their savings (1).\n• Change in social attitudes (1): more acceptable to borrow to buy items (1).", "sources": []}, {"key": "sp2-4c", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 4, "id": "4(c)", "marks": 6, "text": "Analyse two reasons why fewer people may have decided to become teachers.", "intro": "Norway: a decline in the number of people deciding to become teachers.", "type": "written", "lesson": "CIEE09", "ms": "1 mark for identifying each reason (up to 2); remaining marks for analysis:\n• Wages of teachers may have declined / be low (1), less financially rewarding / could earn more elsewhere (1), perhaps due to reduced bargaining power (1).\n• Working conditions may be poor (1): long hours (1), large classes (1), poor behaviour (1), more administrative work (1).\n• Qualifications needed may have increased (1): longer training (1), high cost of training (1).", "sources": []}, {"key": "sp2-4d", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 4, "id": "4(d)", "marks": 8, "text": "Discuss whether or not consumers would benefit from more firms competing in the electric car market.", "intro": "Norway: more than 60% of new cars sold are electric; production makes extensive use of the division of labour.", "type": "written", "lesson": "CIEE10", "ms": "Levels of response (8 marks) as for 2(d).\nWhy consumers would benefit: better quality; lower prices as consumers can switch; more choice and variety; cars to meet different needs; less pollution with more electric and fewer petrol cars; more consumer power; less risk of diseconomies of scale.\nWhy they would not: smaller firms may not gain economies of scale, especially technical economies, which are significant in electric car production; average costs and prices may be higher; fewer, larger firms may have more funds to invest in quality.", "sources": []}, {"key": "sp2-5a", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 5, "id": "5(a)", "marks": 2, "text": "Identify two reasons why a government may want a lower foreign exchange rate.", "intro": "In 2023, the foreign exchange rate of Laos fell from 1LAK (Laotian kip) = $0.0005 to 1LAK = $0.0004. In that year, 53 000 Laotian students went to university, an increase from 42 000 students in 2010. The Laotian Government aims to increase investment to increase the number of students going to university and to lower unemployment. It also aims to reduce inflation, which rose to 25% in 2023, and to attract more foreign multinational companies (MNCs).", "type": "written", "lesson": "CIEE22", "ms": "1 mark for each reason (up to 2): improve the current account / increase exports; increase economic growth; increase employment / lower unemployment; lack of foreign exchange reserves to maintain the current value.", "sources": []}, {"key": "sp2-5b", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 5, "id": "5(b)", "marks": 4, "text": "Explain how opportunity cost influences whether a school leaver decides to go to university.", "intro": "Laos: 53 000 students went to university in 2023, up from 42 000 in 2010.", "type": "written", "lesson": "CIEE01", "ms": "Up to 2 marks for understanding opportunity cost and up to 2 for application (or up to 4 for application with implicit understanding):\n• Opportunity cost is the (next) best alternative (1) forgone / given up (1).\n• A university student gives up the opportunity to start a full-time job (1).\n• The student considers the loss of earnings in the short run (1) and the potential higher earnings with a degree (1).\n• The student compares the satisfaction from studying with the satisfaction from working (1).", "sources": []}, {"key": "sp2-5c", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 5, "id": "5(c)", "marks": 6, "text": "Analyse how a decrease in investment may increase poverty.", "intro": "The Laotian Government aims to increase investment to increase the number of students going to university and to lower unemployment.", "type": "written", "lesson": "CIEE18", "ms": "1 mark for understanding investment and 1 for poverty; remaining marks for analysis (or up to 6 for analysis with implicit understanding):\n• Investment is spending on capital goods (1); less investment may reduce output (1), raise unemployment (1), reduce incomes (1), so people struggle to buy necessities (1), increasing absolute poverty (1).\n• Less investment in education / training / healthcare (1) may reduce skills / productivity (1), lowering some wages (1), widening the gap between rich and poor (1), increasing relative poverty (1).\n• Firms using older equipment (1) may have higher average costs (1), raising prices (1) and reducing purchasing power (1).", "sources": []}, {"key": "sp2-5d", "paper": "sp-p2", "paperLabel": "Specimen Paper 2 (Structured questions)", "q": 5, "id": "5(d)", "marks": 8, "text": "Discuss whether or not attracting more foreign MNCs will reduce inflation.", "intro": "Laos: inflation rose to 25% in 2023; the government aims to attract more foreign MNCs.", "type": "written", "lesson": "CIEE17", "ms": "Levels of response (8 marks) as for 2(d).\nWhy it will: MNCs may use advanced technology with low costs; well-trained, productive workers lower costs; lower costs reduce cost-push inflation; more competition with domestic firms restricts price rises; less need for expensive imports subject to tariffs.\nWhy it will not: MNCs may eliminate domestic producers and then raise prices; may pay higher wages, increasing total demand; more exports increase total demand; higher total demand may cause demand-pull inflation; may deplete natural resources so resources must be imported.", "sources": []}]};
